-- Database: smart_air

SET NAMES utf8mb4;
SET time_zone = '+00:00';
SET FOREIGN_KEY_CHECKS = 0;

DROP DATABASE IF EXISTS `smart_air`;
CREATE DATABASE `smart_air` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `smart_air`;

CREATE TABLE `location` (
  `id` INT NOT NULL,
  `code` VARCHAR(10) NOT NULL,
  `province` VARCHAR(100) NOT NULL,
  `latitude` DECIMAL(9,6) NULL,
  `longitude` DECIMAL(9,6) NULL,
  `created_at` DATETIME(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_location_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `pm_actual` (
  `id` INT NOT NULL,
  `location_id` INT NOT NULL,
  `date` DATE NOT NULL,
  `pm` DECIMAL(8,4) NULL,
  `temp` DECIMAL(5,2) NULL,
  `dew_point` DECIMAL(5,2) NULL,
  `humidity` SMALLINT NULL,
  `pressure` DECIMAL(7,2) NULL,
  `wind_speed` DECIMAL(5,2) NULL,
  `precipitation` DECIMAL(6,2) NULL,
  `wind_direction` DECIMAL(5,2) NULL,
  `fetched_at` DATETIME(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pm_actual_location_date` (`location_id`, `date`),
  KEY `idx_pm_actual_date` (`date`),
  KEY `idx_pm_actual_location_id` (`location_id`),
  CONSTRAINT `fk_pm_actual_location` FOREIGN KEY (`location_id`) REFERENCES `location` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `pm_prediction` (
  `id` INT NOT NULL,
  `pm_actual_id` INT NOT NULL,
  `predicted_for` DATE NOT NULL,
  `pm_predicted` DECIMAL(8,4) NULL,
  `predicted_at` DATETIME(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pm_prediction_actual_date` (`pm_actual_id`, `predicted_for`),
  KEY `idx_pm_prediction_actual_id` (`pm_actual_id`),
  KEY `idx_pm_prediction_for` (`predicted_for`),
  CONSTRAINT `fk_pm_prediction_actual` FOREIGN KEY (`pm_actual_id`) REFERENCES `pm_actual` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `account` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `username` VARCHAR(50) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `role` ENUM('ADMIN','USER') NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_account_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

